        if (!im || im.tagName !== 'IMG' || !im.naturalWidth) return null;
        const c = document.createElement('canvas'), w = 24, h = 24; c.width = w; c.height = h; const x = c.getContext('2d'); x.drawImage(im, 0, 0, w, h);
