/* ---------- PAGOS, ENVÍOS Y FINALIZAR COMPRA (se configura en pagos-config.js) ---------- */
function payCfg(){
    const d = { checkout: true, pedidosEndpoint: '', transferencia: { activo: true, titular: '', bancos: [], nequi: '', llave: '' }, wompi: { activo: false, endpoint: '' }, addi: { activo: false, endpoint: '' } };
    const u = (typeof AJ_PAGOS !== 'undefined' && AJ_PAGOS) ? AJ_PAGOS : {};
    return Object.assign({}, d, u, { transferencia: Object.assign({}, d.transferencia, u.transferencia || {}), wompi: Object.assign({}, d.wompi, u.wompi || {}), addi: Object.assign({}, d.addi, u.addi || {}) });
}
function shipCfg(){
    const d = { gratis: ['bogota'], tarifas: { pequeno: 0, mediano: 0, grande: 0 }, tamanos: { celulares: 'pequeno', audio: 'pequeno', smartwatch: 'pequeno', cargadores: 'pequeno', fundas: 'pequeno', accesorios: 'pequeno', computacion: 'pequeno', estilo: 'pequeno', hogar: 'pequeno', redes: 'pequeno', almacenamiento: 'pequeno', perifericos: 'mediano', tablets: 'mediano', portatiles: 'mediano', impresion: 'grande', monitores: 'grande', televisores: 'grande', computadores: 'grande', energia: 'grande' }, recargos: {}, seguroPct: 0 };
    const u = (typeof AJ_ENVIOS !== 'undefined' && AJ_ENVIOS) ? AJ_ENVIOS : {};
    return Object.assign({}, d, u, { tarifas: Object.assign({}, d.tarifas, u.tarifas || {}), tamanos: Object.assign({}, d.tamanos, u.tamanos || {}), recargos: Object.assign({}, d.recargos, u.recargos || {}) });
}
function normCity(s){ return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim(); }
function isBogota(city){ const c = normCity(city); return !!c && shipCfg().gratis.some(g => { g = normCity(g); return c === g || c.startsWith(g + ' '); }); }
function calcShipping(city, items, subtotal){
    const phys = items.filter(i => getP(i.id) && getP(i.id).category !== 'software');
    if (!phys.length) return { cost: 0, known: true, label: 'Entrega digital' };
    if (isBogota(city)) return { cost: 0, known: true, label: 'Gratis en Bogotá' };
    if (!String(city || '').trim()) return { cost: null, known: false, label: 'Escribe tu ciudad' };
    const c = shipCfg(), order = ['pequeno', 'mediano', 'grande'];
    let tier = 'pequeno'; phys.forEach(i => { const t = c.tamanos[getP(i.id).category] || 'mediano'; if (order.indexOf(t) > order.indexOf(tier)) tier = t; });
    const base = c.tarifas[tier]; if (!base) return { cost: null, known: false, label: 'Por confirmar' };
    let cost = base + (c.recargos[normCity(city)] || 0) + (c.seguroPct ? subtotal * c.seguroPct : 0);
    cost = Math.round(cost / 100) * 100; return { cost, known: true, label: fmt(cost) };
}
