/* ---------- ESTADÍSTICAS DE VISITAS (opcional: se activan desde ajustes.js / panel) ---------- */
function track(name, params){ try { if (window._gaOn && window.gtag) window.gtag('event', name, params || {}); } catch (e) {} }
function gaItem(p, opt, qty){ return { item_id: String(p.id), item_name: p.title, item_brand: p.brand || '', item_category: catName(p.category), item_variant: opt || '', price: p.price || 0, quantity: qty || 1 }; }
function cookieBanner(done){
    const d = document.createElement('div'); d.className = 'ck-banner'; d.setAttribute('role', 'dialog'); d.setAttribute('aria-label', 'Cookies de estadística');
    d.innerHTML = '<p><b>Cookies de estadística</b><br>Usamos Google Analytics para saber cuántas personas visitan la tienda y mejorarla. ¿Aceptas?</p><div><button class="ck-no">No, gracias</button><button class="ck-yes">Aceptar</button></div>';
    d.querySelector('.ck-yes').onclick = () => { done(true); d.remove(); };
    d.querySelector('.ck-no').onclick = () => { done(false); d.remove(); };
    document.body.appendChild(d);
}
function initAnalytics(){
    const gid = (typeof AJ_ANALITICA !== 'undefined' && AJ_ANALITICA) ? String(AJ_ANALITICA).trim() : '';
    const cf = (typeof AJ_CLOUDFLARE !== 'undefined' && AJ_CLOUDFLARE) ? String(AJ_CLOUDFLARE).trim() : '';
    if (cf && /^[a-z0-9]{20,64}$/i.test(cf) && !document.getElementById('cfBeacon')) {   // Cloudflare: sin cookies, sin aviso
        const s = document.createElement('script'); s.defer = true; s.id = 'cfBeacon'; s.src = 'https://static.cloudflareinsights.com/beacon.min.js';
        s.setAttribute('data-cf-beacon', JSON.stringify({ token: cf })); document.head.appendChild(s);
    }
    if (gid && /^G-[A-Z0-9]{6,14}$/i.test(gid)) {                                          // Google Analytics: solo con aceptación
        const load = () => {
            if (window._gaOn) return; window._gaOn = true; window.dataLayer = window.dataLayer || [];
            window.gtag = function () { window.dataLayer.push(arguments); };
            const s = document.createElement('script'); s.async = true; s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(gid); document.head.appendChild(s);
            window.gtag('js', new Date()); window.gtag('config', gid, { anonymize_ip: true });
        };
        let c = null; try { c = localStorage.getItem('nikotech_cookies'); } catch (e) {}
        if (c === 'si') load(); else if (c !== 'no') cookieBanner(ok => { try { localStorage.setItem('nikotech_cookies', ok ? 'si' : 'no'); } catch (e) {} if (ok) load(); });
    }
    document.addEventListener('click', e => {                                              // clics a WhatsApp
        const a = e.target.closest && e.target.closest('a[href*="wa.me"]');
        if (a) track('click_whatsapp', { link_text: (a.textContent || '').trim().slice(0, 40), page_path: location.pathname });
    }, true);
}

/* ---------- AJUSTES DEL DUEÑO (archivo ajustes.js / panel.html) ---------- */
function legacyKeys(obj){ if (!obj || typeof obj !== 'object') return obj; const o = {}; Object.entries(obj).forEach(([k, v]) => { o[LEGACY_COLORS[k] || k] = v; }); return o; }
function makeNuevo(n){
    const price = Number(n.precio) || 0, antes = Number(n.antes) || 0, id = Number(n.id);
    const cat = (typeof CATEGORIES !== 'undefined' && CATEGORIES.some(c => c.id === n.categoria)) ? n.categoria : 'accesorios';
    const p = { id, title: String(n.titulo || '').trim(), brand: String(n.marca || '').trim(), category: cat, price,
        description: String(n.descripcion || '').trim(), features: (n.caracteristicas || []).map(x => String(x).trim()).filter(Boolean),
        image: n.imagen ? (/^(https?:|img\/)/.test(n.imagen) ? n.imagen : 'img/' + n.imagen) : 'img/' + id + '.webp', ph: 1, manual: true, f: {} };
    const ops = (n.opciones || []).filter(o => o && String(o.etiqueta || '').trim());
    if (ops.length) { p.options = ops.map(o => ({ label: String(o.etiqueta).trim(), price: Number(o.precio) || price })); const ps = p.options.map(o => o.price).filter(Boolean); if (ps.length) p.price = Math.min(...ps); }
    if (antes > p.price && p.price) { const pct = Math.round((1 - p.price / antes) * 100); if (pct >= 3) { p.oldPrice = antes; p.badge = '-' + pct + '%'; } }
    return p;
}
function addNuevos(){
    if (typeof AJ_NUEVOS === 'undefined' || !Array.isArray(AJ_NUEVOS)) return;
    AJ_NUEVOS.slice().reverse().forEach(n => { if (!n || !n.id || !n.titulo || ALL_PRODUCTS.some(x => x.id === +n.id)) return; const p = makeNuevo(n); products.unshift(p); ALL_PRODUCTS.unshift(p); });
}
function applyAjustes(){
    addNuevos();
    const has = n => { try { return typeof eval(n) !== 'undefined'; } catch (e) { return false; } };
    if (has('AJ_OCULTOS') && AJ_OCULTOS.length) { const s = new Set(AJ_OCULTOS); for (let i = products.length - 1; i >= 0; i--) if (s.has(products[i].id)) products.splice(i, 1); }
    if (has('AJ_NOMBRES')) Object.entries(AJ_NOMBRES).forEach(([id, n]) => { const p = getP(+id); if (p && n) p.title = n; });
    if (has('AJ_IMAGENES')) Object.entries(AJ_IMAGENES).forEach(([id, f]) => { const p = getP(+id); if (p && f) p.image = /^(https?:|img\/)/.test(f) ? f : 'img/' + f; });
    if (has('AJ_PRECIOS')) Object.entries(AJ_PRECIOS).forEach(([id, c]) => {
        const p = getP(+id); if (!p || !c) return;
        const pr = v => (v && typeof v === 'object') ? v : { precio: v };
        if (c.opciones && hasOpts(p)) {
            let touchedOld = false;
            Object.entries(c.opciones).forEach(([lab, v]) => {
                const o = p.options.find(o => o.label === lab); if (!o) return; const x = pr(v);
                if (x.precio) o.price = x.precio;
                if (x.colores) { o.cp = Object.assign({}, o.cp || {}); Object.entries(legacyKeys(x.colores)).forEach(([k, v]) => { if (v) o.cp[k] = v; else delete o.cp[k]; }); if (!Object.keys(o.cp).length) delete o.cp; }
                if ('antes' in x) { touchedOld = true; if (x.antes) o.old = x.antes; else delete o.old; }
            });
            const base = p.options.reduce((a, o) => (!a || o.price < a.price) ? o : a, null);
            if (base) { p.price = base.price; if (touchedOld) { if (base.old) p.oldPrice = base.old; else delete p.oldPrice; } }
        } else if (!hasOpts(p)) {
            if (c.precio) p.price = c.precio;
            if ('antes' in c) { if (c.antes) p.oldPrice = c.antes; else delete p.oldPrice; }
        }
        if (p.oldPrice && p.price && p.oldPrice > p.price) {
            const pct = Math.round((1 - p.price / p.oldPrice) * 100);
            if (pct >= 3) p.badge = '-' + pct + '%'; else if (p.badge && p.badge[0] === '-') delete p.badge;
        } else if (p.badge && p.badge[0] === '-') delete p.badge;
    });
    products.forEach(p => { if (p.colors && !p.colorsAll) p.colorsAll = p.colors.slice(); });
    if (has('AJ_COLORES')) Object.entries(AJ_COLORES).forEach(([id, c]) => {
        const p = getP(+id); if (!p || !p.colorsAll || !c) return;
        const oc = (c.ocultos || []).map(z => LEGACY_COLORS[z] || z), df = LEGACY_COLORS[c.defecto] || c.defecto;
        p.colors = p.colorsAll.filter(x => !oc.includes(x.n)); if (!p.colors.length) p.colors = p.colorsAll.slice();
        if (df && p.colors.some(x => x.n === df)) p.defColor = df; else if (p.defColor && !p.colors.some(x => x.n === p.defColor)) delete p.defColor;
        if (c.imagenes) p.colorImgs = legacyKeys(c.imagenes);
    });
    if (has('AJ_DESTACADOS') && AJ_DESTACADOS.length) {
        products.forEach(p => { p.featured = false; delete p.fr; });
        AJ_DESTACADOS.forEach((id, i) => { const p = getP(id); if (p) { p.featured = true; p.fr = i + 1; } });
        const g = document.getElementById('productsGrid'); if (g && g.dataset.limit) g.dataset.limit = Math.min(12, Math.max(4, AJ_DESTACADOS.length));
    }
}

