    if (!t || t.tagName !== 'IMG') return;
    if (t.dataset.fblist) { const a = t.dataset.fblist.split('|').filter(Boolean); if (a.length) { t.src = a.shift(); t.dataset.fblist = a.join('|'); return; } }
    if (t.dataset.ph) { t.replaceWith(phNode(t)); return; }
    if (/\/img\//.test(t.src) && !t.dataset.fb) { t.dataset.fb = 1; t.src = t.src.replace('/img/', '/'); }
